import React, { useEffect, useRef, useState } from "react";
import * as tmImage from "@teachablemachine/image";

const MODEL_PATH = process.env.PUBLIC_URL + "/model/";

function Class() {
  const [statusText, setStatusText] = useState("Loading model...");
  const [prediction, setPrediction] = useState("");
  const [model, setModel] = useState(null);
  const [previewUrl, setPreviewUrl] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [inputMode, setInputMode] = useState("upload");
  const [isWebcamActive, setIsWebcamActive] = useState(false);
  const [webcamCaptureUrl, setWebcamCaptureUrl] = useState("");
  const [isCapturing, setIsCapturing] = useState(false);

  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const isPredictingRef = useRef(false);

  const isAnalyzing = statusText === "Analyzing image...";

  useEffect(() => {
    const loadModel = async () => {
      try {
        const modelURL = MODEL_PATH + "model.json";
        const metadataURL = MODEL_PATH + "metadata.json";

        const loadedModel = await tmImage.load(modelURL, metadataURL);

        setModel(loadedModel);
        setStatusText("Model ready. Upload an image to classify.");
      } catch (error) {
        console.error(error);
        setStatusText("Error loading model");
      } finally {
        setIsLoading(false);
      }
    };

    loadModel();
  }, []);

  const updatePrediction = async (img) => {
    if (!model || isPredictingRef.current) return;

    isPredictingRef.current = true;

    try {
      const predictions = await model.predict(img);
      const top = predictions.reduce((a, b) =>
        a.probability > b.probability ? a : b
      );

      setPrediction(`${top.className} (${(top.probability * 100).toFixed(2)}%)`);
      setStatusText("Prediction complete");
    } catch (err) {
      console.error(err);
      setStatusText("Prediction error");
    }

    isPredictingRef.current = false;
  };

  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const url = window.URL.createObjectURL(file);

    setPreviewUrl(url);
    setPrediction("");
    setStatusText("Analyzing image...");

    const img = new Image();
    img.src = url;
    img.onload = () => updatePrediction(img);
  };

  const startWebcam = async () => {
    const stream = await navigator.mediaDevices.getUserMedia({ video: true });
    streamRef.current = stream;

    if (videoRef.current) {
      videoRef.current.srcObject = stream;
      await videoRef.current.play();
    }

    setIsWebcamActive(true);
  };

  const stopWebcam = () => {
    streamRef.current?.getTracks().forEach((t) => t.stop());
    setIsWebcamActive(false);
  };

  const captureFromWebcam = () => {
    const video = videoRef.current;
    const canvas = document.createElement("canvas");

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    const ctx = canvas.getContext("2d");
    ctx.drawImage(video, 0, 0);

    setStatusText("Analyzing...");
    setIsCapturing(true);

    canvas.toBlob((blob) => {
      const url = window.URL.createObjectURL(blob);
      setWebcamCaptureUrl(url);

      const img = new Image();
      img.src = url;
      img.onload = () => {
        updatePrediction(img);
        setIsCapturing(false);
      };
    });
  };

  return (
    <section className="classifier">

      <div className="mode-switch">
        <button
          className={`mode-btn ${inputMode === "upload" ? "active" : ""}`}
          onClick={() => setInputMode("upload")}
        >
          Upload Image
        </button>

        <button
          className={`mode-btn ${inputMode === "webcam" ? "active" : ""}`}
          onClick={() => setInputMode("webcam")}
        >
          Use Webcam
        </button>
      </div>

      {inputMode === "upload" && (
        <>
          <label className="upload-cta">
            <input type="file" accept="image/*" onChange={handleImageUpload} />
            <span>Choose an Image</span>
          </label>

          {previewUrl && (
            <div className="preview-wrap reveal-in">
              <img src={previewUrl} className="preview-image" alt="preview" />
            </div>
          )}
        </>
      )}

      {inputMode === "webcam" && (
        <>
          <div className="webcam-actions">
            <button
              className="control-btn"
              onClick={isWebcamActive ? stopWebcam : startWebcam}
            >
              {isWebcamActive ? "Stop Camera" : "Start Camera"}
            </button>

            <button
              className="control-btn capture-btn"
              onClick={captureFromWebcam}
              disabled={!isWebcamActive}
            >
              Capture Photo
            </button>
          </div>

          <div className="webcam-panels reveal-in">

            <div className="preview-wrap webcam-frame">
              <div className={`webcam-stage ${isWebcamActive ? "has-feed" : ""}`}>
                <video ref={videoRef} className="webcam-video" autoPlay muted />
              </div>
            </div>

            <div className="preview-wrap captured-frame">
              {webcamCaptureUrl ? (
                <img src={webcamCaptureUrl} className="preview-image" alt="capture" />
              ) : (
                <div className="capture-placeholder">
                  Captured photo will appear here
                </div>
              )}
            </div>

          </div>
        </>
      )}

      <p className={`status-text ${isAnalyzing ? "is-busy" : ""}`}>
        {statusText}
      </p>

      {prediction && (
        <h2 className="prediction-pill pop-in">
          {prediction}
        </h2>
      )}
    </section>
  );
}

export default Class;